<script>
(function() {
    // Relative DOM elements query targeting the current message block
    const wrapper = document.currentScript.previousElementSibling;
    const container = wrapper.querySelector('.newspaper-container');
    const rawCapsule = wrapper.querySelector('.raw-newday-capsule');
    const rawText = rawCapsule ? rawCapsule.value : '';

    // Bind debug panel
    const debugPre = wrapper.querySelector('.debug-text');
    if (debugPre) debugPre.innerText = rawText;

    const themes = ['sepia', 'dark-aged', 'parchment'];
    let themeIdx = 0;
    const fontSizes = [12, 13, 14, 15, 16];
    let fsIdx = 1;

    // Interactive events bounded locally to avoid id conflicts
    wrapper.querySelector('.btn-toggle-theme').addEventListener('click', function() {
        themeIdx = (themeIdx + 1) % themes.length;
        const t = themes[themeIdx];
        if (t === 'sepia') container.removeAttribute('data-theme');
        else container.setAttribute('data-theme', t);
    });

    wrapper.querySelector('.btn-adjust-fs').addEventListener('click', function() {
        fsIdx = (fsIdx + 1) % fontSizes.length;
        container.style.setProperty('--base-fs', fontSizes[fsIdx] + 'px');
    });

    function getTag(str, tag) {
        const m = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i').exec(str);
        return m ? m[1].trim() : null;
    }

    function parseRawContent(raw) {
        let text = raw.replace(/<\/?Newday>/gi, '').trim();

        function getKeyVal(str, key) {
            const xmlVal = getTag(str, key);
            if (xmlVal !== null) return xmlVal;
            const m = new RegExp(`(?:^|\\n)\\s*-?\\s*${key}\\s*:\\s*(?:"([^"]+)"|'([^']+)'|([^\\n\\r]+))`, 'i').exec(str);
            if (m) {
                let val = (m[1] || m[2] || m[3] || '').trim();
                if (val === '|') return null;
                return val;
            }
            return '';
        }

        // 1. Locate main sections
        const idxWeather = text.indexOf('date_and_weather:');
        const idxNews = text.indexOf('today_news:');
        const idxBill = text.indexOf('yesterday_bill:');

        const weatherRaw = idxWeather !== -1 ? text.slice(idxWeather, idxNews !== -1 ? idxNews : undefined).trim() : text;
        const newsRaw = idxNews !== -1 ? text.slice(idxNews, idxBill !== -1 ? idxBill : undefined).trim() : '';
        const billRaw = idxBill !== -1 ? text.slice(idxBill).trim() : '';

        // 1. Date & Weather
        const dateMatch = weatherRaw.match(/date:\s*["']?([^"\n]+)["']?/i) || weatherRaw.match(/(\d{4}年\d{1,2}月\d{1,2}日\s*[^,\n\r]*)/);
        const date = dateMatch ? dateMatch[1].trim() : '1925年6月13日 · 星期六';
        const location = getKeyVal(weatherRaw, 'location') || '悉尼';

        let weather = getKeyVal(weatherRaw, 'weather');
        if (!weather) {
            const wMatch = weatherRaw.match(/weather\s*:\s*(?:"([^"]+)"|'([^']+)'|\|?\s*([\s\S]+?)(?=\n\s*\w+\s*:|\n\s*<\/?|$))/i);
            weather = wMatch ? (wMatch[1] || wMatch[2] || wMatch[3] || '').trim() : '';
        }

        // 2. News
        const newsName = getKeyVal(newsRaw, 'newspaper_name') || '《悉尼先驱晨报》';
        const issueNo = getKeyVal(newsRaw, 'issue_no') || '';
        const headline = getKeyVal(newsRaw, 'headline') || '';

        const bulletins = [];
        if (newsRaw) {
            const bulletBlocks = newsRaw.split(/(?=\n\s*-\s*title:|\n\s*title:)/i);
            for (let i = 1; i < bulletBlocks.length; i++) {
                const block = bulletBlocks[i];
                const title = getKeyVal(block, 'title') || '城中快讯';
                let contentVal = getKeyVal(block, 'content');
                if (contentVal === '') {
                    const match = block.match(/content\s*:\s*(?:"([^"]+)"|'([^']+)'|\|?\s*([\s\S]+?)(?=\n\s*-\s*\w+\s*:|\n\s*\w+\s*:|$))/i);
                    contentVal = match ? (match[1] || match[2] || match[3] || '').trim() : '';
                }
                bulletins.push({ title, content: contentVal });
            }
        }

        // 3. Bill
        const cashBefore = getKeyVal(billRaw, 'team_cash_before') || getKeyVal(billRaw, 'cash_before') || '0.00';
        const totalCost = getKeyVal(billRaw, 'total_cost') || getKeyVal(billRaw, 'total_deducted') || '0.00';
        const cashAfter = getKeyVal(billRaw, 'team_cash_after') || getKeyVal(billRaw, 'cash_after') || '0.00';

        const items = [];
        if (billRaw) {
            const itemBlocks = billRaw.split(/(?=\n\s*-\s*category:|\n\s*category:)/i);
            for (let i = 1; i < itemBlocks.length; i++) {
                const block = itemBlocks[i];
                const category = getKeyVal(block, 'category') || '消费支出';
                const tier = getKeyVal(block, 'tier') || '【标准】';
                const cost = getKeyVal(block, 'cost') || '0.00';

                let details = '';
                const detMatch = block.match(/details\s*:\s*(?:\|?\s*)([\s\S]+?)(?=\n\s*(?:-\s*)?category:|\n\s*total_cost:|\n\s*total-cost:|\n\s*team_cash_after:|\n\s*team-cash-after:|$)/i);
                if (detMatch) {
                    details = detMatch[1].trim();
                    if ((details.startsWith('"') && details.endsWith('"')) || (details.startsWith("'") && details.endsWith("'"))) {
                        details = details.slice(1, -1).trim();
                    }
                }
                items.push({ category, tier, cost, details });
            }
        }

        return { date, location, weather, newsName, issueNo, headline, bulletins, cashBefore, totalCost, cashAfter, items };
    }

    try {
        const data = parseRawContent(rawText);

        // Populate header
        wrapper.querySelector('.paper-name-val').innerText = data.newsName;
        wrapper.querySelector('.issue-no-val').innerText = data.issueNo;
        wrapper.querySelector('.date-display-val').innerText = data.date;
        wrapper.querySelector('.loc-display-val').innerText = data.location;

        // Clean and display date badge
        let cleanDate = data.date.split('·')[0].trim().split(' ')[0].trim();
        wrapper.querySelector('.date-badge-val').innerText = cleanDate;
        wrapper.querySelector('.weather-text-val').innerText = data.weather;
        wrapper.querySelector('.main-headline-val').innerText = data.headline;

        // News Layout
        let newsHTML = '<div class="news-column">';
        data.bulletins.forEach((b, i) => {
            if (i > 0 && i === Math.ceil(data.bulletins.length / 2)) newsHTML += '</div><div class="news-column">';
            newsHTML += `<article class="news-card"><h3 class="news-card-title">${b.title}</h3><p class="news-card-content">${b.content}</p></article>`;
        });
        newsHTML += '</div>';
        wrapper.querySelector('.news-columns-val').innerHTML = newsHTML;

        // Cash Summary (clean formatting)
        const cBefore = parseFloat(String(data.cashBefore).replace(/[^0-9.]/g, '') || 0).toFixed(2);
        const cDeduct = parseFloat(String(data.totalCost).replace(/[^0-9.]/g, '') || 0).toFixed(2);
        const cAfter = parseFloat(String(data.cashAfter).replace(/[^0-9.]/g, '') || 0).toFixed(2);

        wrapper.querySelector('.cash-before-val').innerText = '$' + cBefore;
        wrapper.querySelector('.cash-deduct-val').innerText = '-$' + cDeduct;
        wrapper.querySelector('.cash-after-val').innerText = '$' + cAfter;

        // Bill Items
        const tierMap = {
            '【本地】': 'tier-local',
            '【经济】': 'tier-economy',
            '【标准】': 'tier-standard',
            '【高档】': 'tier-highend',
            '【奢华】': 'tier-luxury'
        };

        function getIconForCategory(cat) {
            if (cat.includes('住宿') || cat.includes('房') || cat.includes('宿')) return '🏨';
            if (cat.includes('餐') || cat.includes('食') || cat.includes('饮') || cat.includes('午餐') || cat.includes('晚餐')) return '🍽️';
            if (cat.includes('交') || cat.includes('车') || cat.includes('汽') || cat.includes('船') || cat.includes('路费')) return '🚕';
            if (cat.includes('电') || cat.includes('信') || cat.includes('邮') || cat.includes('报')) return '✉️';
            if (cat.includes('杂') || cat.includes('零')) return '📦';
            if (cat.includes('医') || cat.includes('药') || cat.includes('伤') || cat.includes('诊')) return '🏥';
            if (cat.includes('武器') || cat.includes('枪') || cat.includes('弹')) return '🔫';
            return '🪙';
        }

        let billHTML = '';
        data.items.forEach(item => {
            const cleanTier = item.tier.replace(/[【】\[\]]/g, '').trim();
            let tierClass = 'tier-standard';
            for (const key in tierMap) {
                if (key.includes(cleanTier)) {
                    tierClass = tierMap[key];
                    break;
                }
            }
            const icon = getIconForCategory(item.category);
            const formattedCost = parseFloat(String(item.cost).replace(/[^0-9.]/g, '') || 0).toFixed(2);
            billHTML += `<div class="bill-item">
                <div class="bill-item-header">
                    <div class="bill-category"><span>${icon} ${item.category}</span><span class="tier-badge ${tierClass}">【${cleanTier}】</span></div>
                    <div class="bill-cost">-$${formattedCost}</div>
                </div>
                <div class="bill-details">${item.details}</div>
            </div>`;
        });
        wrapper.querySelector('.bill-list-val').innerHTML = billHTML;

    } catch(e) {
        console.error("Newday Render Error:", e);
    }
})();
</script>
